/*
 * PG07 — preset importe de Lightroom.
 *
 * GENERE PAR `scripts/import-lightroom-preset.mjs`. Ne pas editer a la main:
 * relancer l'import si le preset change dans Lightroom.
 *
 * La couleur vient d'une Hald CLUT passee dans Lightroom: ce n'est pas une
 * approximation des calculs d'Adobe, c'est leur resultat mesure sur toute la
 * grille RVB (ecart moyen a l'identite: 32.8/255, max 217/255).
 *
 * Reglages lus dans le .xmp ou releves dans Lightroom:
 *   (aucun .xmp fourni : preset Premium Adobe relève à l’écran)
 * Reglages hors LUT effectivement importes:
 *   - clarity: -13
 *   - presetSpatialBeforeLut: true
 *   - presetClarityScale: 0.18
 *
 * Source Hald : pg07.jpg (niveau 8, cube 64)
 * Importe le  : 2026-08-30
 */

import { lutFromBase64 } from '../haldClut.js';

const LUT_BASE64 = '';

let cached = null;

export const preset = {
    id: 'pg07',
    label: "PG07",
    collection: {"id":"portrait-groupe","label":"Portrait groupe"},
    hint: "Lightroom — Portraits : Groupe",
    description: "Capturé depuis Lightroom par table de conversion complète.",
    bestFor: "Portrait groupe",
    avoidFor: "photos déjà fortement filtrées",
    recommendedIntensity: 100,
    /* Reglages que la table ne peut pas porter (ils dependent des pixels
       voisins ou de la position dans l'image), lus dans le .xmp. */
    spatialFilters: {"clarity":-13,"presetSpatialBeforeLut":true,"presetClarityScale":0.18},
    /* La table elle-meme, decodee au premier usage. */
    getLut() {
        if (!cached) cached = lutFromBase64(LUT_BASE64);
        return cached;
    },
};

export default preset;
